      "src": 0,
      "kind": "poc",
      "quote": "漏洞PoC已在互联网出现。"
    }
  ],
  "fixed_version": "2.17.1",
  "summary_zh": "若攻击者控制 Log4j2 配置，JDBC Appender 指向 JNDI URI 可 RCE，升级 2.17.1。"
